"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import { DiagramFrame, NodeCard } from "@diax/ui-react/presentation";
import type { DiaxRelation } from "diax";
import type { ReactNode } from "react";

const relations = [
  relation("assess-isolate", "assess", "isolate", "triage accepted"),
  relation("isolate-patch", "isolate", "patch", "affected artifact"),
  relation("isolate-escalate", "isolate", "escalate", "if scope expands", {
    color: "#a96320",
    strokeDasharray: "3 3",
  }),
  relation("escalate-patch", "escalate", "patch", "owner approval", { color: "#a96320" }),
  relation("patch-verify", "patch", "verify", "signed patch"),
  relation("verify-close", "verify", "close", "recovery confirmed", {
    color: "#47715d",
    strokeDasharray: "7 4",
  }),
] satisfies readonly DiaxRelation<ReactNode>[];

const target = {
  assess: connectionTarget("assess"),
  isolate: connectionTarget("isolate"),
  escalate: connectionTarget("escalate"),
  patch: connectionTarget("patch"),
  verify: connectionTarget("verify"),
  close: connectionTarget("close"),
};

const compactRunbook = [
  { id: "assess", owner: "Security", title: "Assess exposure", note: "Accept triage" },
  { id: "isolate", owner: "Platform", title: "Isolate artifact", note: "Preserve evidence" },
  {
    id: "escalate",
    owner: "Security",
    title: "Escalate scope",
    note: "Conditional when impact expands",
  },
  { id: "patch", owner: "Platform", title: "Publish signed patch", note: "Owner approved" },
  { id: "verify", owner: "Release", title: "Verify recovery", note: "Issue receipt" },
  { id: "close", owner: "Security", title: "Close incident record", note: "Terminal owner" },
] as const;

export default function IncidentResponseWorkflow() {
  return (
    <DiagramFrame
      data-showcase-corpus="incident-response-workflow"
      eyebrow="Incident runbook · Authored responsibility"
      title="One response, three accountable lanes"
      description="The sections remain ordinary runbook DOM. DiaX keeps each handoff attached while the lanes reflow."
      caption="Conditional escalation and recovery acknowledgement remain named when color or connectors are unavailable."
      className="w-full max-w-[1120px] [--diax-accent:#a96320] [--diax-frame-bg:#eef2f3] [--diax-frame-radius:2px] [--diax-frame-shadow:none] [--diax-node-bg:#f9fbfb] [--diax-node-border:#aebbc0] [--diax-node-shadow:none] [--diax-node-text:#172126] [--diax-ui-radius:2px]"
    >
      <RelationLegend />

      <ConnectionSurface
        relations={relations}
        pathType="orthogonal"
        aria-label="Incident response handoffs"
        className="@container mt-4 hidden gap-14 sm:grid [&_[data-diax-ui-node=card]_[data-diax-ui-part=eyebrow]]:text-[11px]"
      >
        <Lane id="incident-security" label="Security" clock="T+00 → T+60">
          <NodeCard
            {...target.assess}
            className="max-w-none @min-[52rem]:col-start-2"
            size="compact"
            eyebrow="T+00 · Intake"
            title="Assess exposure"
            description="Confirm affected versions and user impact."
            tone="warning"
          />
          <NodeCard
            {...target.escalate}
            className="max-w-none @min-[52rem]:col-start-4"
            size="compact"
            eyebrow="Conditional"
            title="Escalate scope"
            description="Name the accountable owner before expanding containment."
            tone="danger"
          />
          <NodeCard
            {...target.close}
            className="max-w-none @min-[52rem]:col-start-5"
            size="compact"
            eyebrow="Terminal"
            title="Close incident record"
            description="Attach the recovery receipt and remaining follow-up."
            tone="success"
          />
        </Lane>

        <Lane id="incident-platform" label="Platform" clock="T+15 → T+45">
          <NodeCard
            {...target.isolate}
            className="max-w-none @min-[52rem]:col-start-2"
            size="compact"
            eyebrow="T+15 · Contain"
            title="Isolate artifact"
            description="Quarantine only the affected release and preserve evidence."
            tone="danger"
          />
          <NodeCard
            {...target.patch}
            className="max-w-none @min-[52rem]:col-start-4"
            size="compact"
            eyebrow="T+45 · Repair"
            title="Publish signed patch"
            description="Produce one versioned candidate with provenance."
            tone="accent"
          />
        </Lane>

        <Lane id="incident-release" label="Release" clock="T+60">
          <NodeCard
            {...target.verify}
            className="max-w-none @min-[52rem]:col-start-5"
            size="compact"
            eyebrow="T+60 · Recover"
            title="Verify recovery"
            description="Replay checks, inspect signals and issue the receipt."
            tone="success"
          />
        </Lane>
      </ConnectionSurface>

      <ol
        data-incident-mobile-runbook
        aria-label="Incident response ordered runbook"
        className="m-0 mt-4 grid list-none border-y border-[#bdc8cc] p-0 sm:hidden"
      >
        {compactRunbook.map((step, index) => (
          <li
            key={step.id}
            data-incident-mobile-step={step.id}
            className="grid grid-cols-[2.5rem_minmax(0,1fr)] gap-3 border-t border-[#d3dcdf] py-3 first:border-t-0"
          >
            <span className="font-mono text-[11px] font-bold text-[#a96320]">
              {String(index + 1).padStart(2, "0")}
            </span>
            <span>
              <strong className="block text-[12px] text-[#172126]">
                {step.owner} · {step.title}
              </strong>
              <small className="mt-1 block text-[11px] leading-4 text-[#5a6970]">
                {step.note}
              </small>
            </span>
          </li>
        ))}
      </ol>
    </DiagramFrame>
  );
}

function Lane({
  id,
  label,
  clock,
  children,
}: {
  id: string;
  label: string;
  clock: string;
  children: ReactNode;
}) {
  return (
    <section
      aria-labelledby={id}
      className="grid min-w-0 gap-4 border border-[#bdc8cc] bg-[#f6f8f8] p-3 @min-[52rem]:grid-cols-[8rem_repeat(4,minmax(0,1fr))] @min-[52rem]:gap-x-10"
    >
      <header className="flex items-baseline justify-between gap-3 border-b border-[#bdc8cc] pb-2 @min-[52rem]:row-span-2 @min-[52rem]:block @min-[52rem]:border-r @min-[52rem]:border-b-0 @min-[52rem]:pr-3 @min-[52rem]:pb-0">
        <h2 id={id} className="m-0 font-mono text-[11px] font-bold uppercase tracking-[0.12em]">
          {label}
        </h2>
        <p className="m-0 mt-1 font-mono text-[9px] text-[#66757c]">{clock}</p>
      </header>
      {children}
    </section>
  );
}

function RelationLegend() {
  const items = [
    { label: "Required handoff", className: "border-[#52666f]" },
    { label: "Conditional escalation", className: "border-[#a96320] border-dashed" },
    { label: "Recovery acknowledgement", className: "border-[#47715d] border-dashed" },
  ];
  return (
    <ul
      aria-label="Incident relation legend"
      className="m-0 grid list-none border-y border-[#bdc8cc] p-0 text-[10px] text-[#526169] sm:grid-cols-3"
    >
      {items.map((item) => (
        <li key={item.label} className="flex items-center gap-2 px-3 py-2 sm:border-l sm:first:border-l-0">
          <span aria-hidden="true" className={`w-8 border-t-2 ${item.className}`} />
          {item.label}
        </li>
      ))}
    </ul>
  );
}

function RelationLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-[#aebbc0] bg-[#f9fbfb] px-1.5 py-0.5 font-mono text-[10px] font-semibold text-[#43545c]">
      {children}
    </span>
  );
}

function relation(
  id: string,
  from: string,
  to: string,
  label: string,
  style: Pick<Exclude<DiaxRelation<ReactNode>, string>, "color" | "strokeDasharray"> = {},
): DiaxRelation<ReactNode> {
  return {
    id,
    from,
    to,
    label: <RelationLabel>{label}</RelationLabel>,
    targetMarker: "arrow",
    gap: 7,
    ...style,
  };
}
